import React from 'react';
import { DropTower } from './index';

const previews = {
  componentName: 'DropTower',
  importPath: 'components/DropTower',
  previews: [
    { name: '3D rig', description: "Vertical drop tower: a ring gondola that climbs then drops.", render: () => <DropTower /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Vertical drop tower modelled from the RCT2 sprite: a lattice tower with a
// ring gondola of outward-facing riders that climbs slowly, then drops.
export function DropTower() {
  return (
    <Stage
      distance={9}
      targetY={2.6}
      build={(t, g) => {
        const H = 5.4;
        g.add(cyl(t, 0.7, 0.8, 0.4, 0x8a8f98, [0, 0.2, 0], { tex: 'concrete', repeat: [6, 1], rough: 0.9, seg: 20 }));
        for (let k = 0; k < 3; k++) {
          const a = (k / 3) * Math.PI * 2;
          g.add(cyl(t, 0.06, 0.06, H, 0xd23a4a, [Math.cos(a) * 0.3, H / 2, Math.sin(a) * 0.3], { tex: 'metal', metal: 0.7, rough: 0.4, seg: 10 }));
        }
        for (let y = 0.6; y < H; y += 0.6) g.add(cyl(t, 0.02, 0.02, 0.62, 0xe6e6ec, [0, y, 0], { rotZ: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 6 }));
        g.add(cyl(t, 0, 0.4, 0.5, 0xf5e050, [0, H + 0.2, 0], { seg: 6, metal: 0.4, rough: 0.4 }));

        const gondola = new t.Group();
        g.add(gondola);
        gondola.add(cyl(t, 0.62, 0.62, 0.16, 0x2f6fd0, [0, 0, 0], { tex: 'plastic', repeat: [10, 1], seg: 22, rough: 0.4 }));
        gondola.add(cyl(t, 0.66, 0.66, 0.05, 0xf5e050, [0, 0.1, 0], { seg: 22 }));
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true, expression: 'surprised' });
          p.group.scale.setScalar(0.4);
          p.group.position.set(Math.cos(a) * 0.42, 0.06, Math.sin(a) * 0.42);
          p.group.rotation.y = -a + Math.PI / 2;
          gondola.add(p.group);
          gondola.add(cyl(t, 0.025, 0.025, 0.5, 0x222226, [Math.cos(a) * 0.42, 0.32, Math.sin(a) * 0.42], { seg: 6, metal: 0.5 }));
        }
        return (time) => {
          const cyc = (time * 0.32) % 1;
          const h = cyc < 0.82 ? cyc / 0.82 : 1 - (cyc - 0.82) / 0.18; // slow climb, fast drop
          gondola.position.y = 0.6 + h * (H - 1.2);
        };
      }}
    />
  );
}

import React from 'react';
import { LogFlume } from './index';

const previews = {
  componentName: 'LogFlume',
  importPath: 'components/LogFlume',
  previews: [
    { name: '3D rig', description: "Log flume water ride: an elevated trough with a log boat of riders.", render: () => <LogFlume /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Log flume modelled from the RCT2 water ride: an elevated wooden trough of
// blue water on posts, with a hollow log boat of riders sliding along it.
export function LogFlume() {
  return (
    <Stage
      distance={7.5}
      targetY={0.9}
      background="#bfe6f2"
      build={(t, g) => {
        const RUN = 6.4;
        g.add(box(t, [1.0, 0.16, RUN], 0x5a3d22, [0, 0.6, 0], { tex: 'wood', repeat: [4, 22], rough: 0.8 }));
        [-0.5, 0.5].forEach((x) => g.add(box(t, [0.1, 0.34, RUN], 0x4a3018, [x, 0.76, 0], { tex: 'wood', repeat: [1, 22], rough: 0.8 })));
        g.add(box(t, [0.84, 0.06, RUN], 0x2a8fd0, [0, 0.74, 0], { emissive: 0x115f9c, rough: 0.2, opacity: 0.9 })); // water
        for (let z = -RUN / 2 + 0.5; z < RUN / 2; z += 1.4)
          [-0.5, 0.5].forEach((x) => g.add(cyl(t, 0.08, 0.09, 0.7, 0x5a3d22, [x, 0.25, z], { tex: 'wood', repeat: [1, 1], rough: 1, seg: 8 })));

        const boat = new t.Group();
        g.add(boat);
        boat.add(cyl(t, 0.32, 0.32, 1.3, 0x7a5230, [0, 0, 0], { rotZ: Math.PI / 2, tex: 'wood', repeat: [6, 2], rough: 0.8, seg: 18 }));
        boat.add(cyl(t, 0.26, 0.26, 1.2, 0x2a1c10, [0, 0.06, 0], { rotZ: Math.PI / 2, seg: 18 })); // hollow
        for (let i = 0; i < 3; i++) {
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[(i + 3) % SHIRTS.length], seated: true, expression: i === 0 ? 'surprised' : 'happy' });
          p.group.scale.setScalar(0.42);
          p.group.position.set(0, 0.12, -0.42 + i * 0.42);
          boat.add(p.group);
        }
        return (time) => {
          const z = ((time * 1.4) % (RUN + 1.5)) - (RUN / 2 + 0.75);
          boat.position.set(0, 0.86, z);
        };
      }}
    />
  );
}

import React from 'react';
import { Monorail } from './index';

const previews = {
  componentName: 'Monorail',
  importPath: 'components/Monorail',
  previews: [
    { name: '3D rig', description: "Elevated monorail beam on piers with a streamlined gliding train.", render: () => <Monorail /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';

// Monorail modelled from the RCT2 transport ride: an elevated concrete beam on
// piers with a streamlined three-car train gliding along it.
export function Monorail() {
  return (
    <Stage
      distance={8}
      targetY={1.4}
      build={(t, g) => {
        const RUN = 7;
        const beamY = 1.2;
        g.add(box(t, [0.42, 0.3, RUN], 0xc4c9d1, [0, beamY, 0], { tex: 'concrete', repeat: [2, 22], rough: 0.85 }));
        for (let z = -RUN / 2 + 0.6; z < RUN / 2; z += 1.6)
          g.add(cyl(t, 0.14, 0.2, beamY, 0x9aa0a8, [0, beamY / 2, z], { tex: 'concrete', repeat: [2, 2], rough: 0.9, seg: 12 }));

        const train = new t.Group();
        g.add(train);
        for (let i = 0; i < 3; i++) {
          const car = new t.Group();
          car.position.z = (i - 1) * 1.15;
          car.add(box(t, [0.5, 0.5, 1.02], 0xeef2f6, [0, beamY + 0.16, 0], { tex: 'plastic', repeat: [2, 2], rough: 0.3 }));
          car.add(box(t, [0.53, 0.16, 0.92], 0x2f6fd0, [0, beamY + 0.12, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.3 }));
          car.add(box(t, [0.44, 0.2, 0.86], 0x152238, [0, beamY + 0.3, 0], { opacity: 0.7, rough: 0.2 }));
          if (i === 0) car.add(box(t, [0.5, 0.46, 0.26], 0xeef2f6, [0, beamY + 0.14, 0.56], { rotX: 0.5, tex: 'plastic', rough: 0.3 }));
          train.add(car);
        }
        return (time) => {
          train.position.z = ((time * 1.7) % (RUN + 2)) - (RUN / 2 + 1);
        };
      }}
    />
  );
}

import React from 'react';
import { HauntedMansion } from './index';

const previews = {
  componentName: 'HauntedMansion',
  importPath: 'components/HauntedMansion',
  previews: [
    { name: '3D rig', description: "A crooked haunted mansion dark ride with flickering windows.", render: () => <HauntedMansion /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';

// Haunted mansion (dark ride) modelled from the RCT2 sprite: a crooked timber
// house with a steep gabled roof, a witch-hat tower, a dead tree and windows
// that flicker with an eerie glow.
export function HauntedMansion() {
  return (
    <Stage
      distance={7.5}
      targetY={1.2}
      background="#5a6b86"
      build={(t, g) => {
        const WALL = 0x4a4658;
        const ROOF = 0x2a2733;
        const wins: THREE.MeshStandardMaterial[] = [];
        const winMat = () => new t.MeshStandardMaterial({ color: 0x2a2410, emissive: 0xffaa22, emissiveIntensity: 1, roughness: 0.5 });

        g.add(box(t, [2.0, 1.6, 1.6], WALL, [0, 0.8, 0], { tex: 'wood', repeat: [5, 4], rough: 0.92, rotZ: 0.01 }));
        [-1, 1].forEach((s) => g.add(box(t, [2.25, 0.12, 1.35], ROOF, [0, 1.92, s * 0.42], { tex: 'wood', repeat: [6, 3], rough: 0.85, rotX: s * 0.72 })));
        // witch-hat tower
        g.add(box(t, [0.72, 2.7, 0.72], WALL, [-0.86, 1.35, 0.15], { tex: 'wood', repeat: [2, 6], rough: 0.92, rotZ: 0.03 }));
        g.add(cyl(t, 0, 0.62, 0.95, ROOF, [-0.86, 3.0, 0.15], { seg: 4, rough: 0.85 }));
        // door
        g.add(box(t, [0.5, 0.92, 0.08], 0x140d06, [0.35, 0.46, 0.82], { tex: 'wood', repeat: [2, 3], rough: 0.85 }));
        g.add(ball(t, 0.03, 0xd0c060, [0.5, 0.5, 0.86], { metal: 0.6, rough: 0.3 }));
        // flickering windows (front + tower)
        const wpos: [number, number][] = [
          [-0.55, 1.12],
          [0.55, 1.14],
          [0.05, 1.15],
        ];
        wpos.forEach(([x, y]) => {
          const m = winMat();
          const w = new t.Mesh(new t.BoxGeometry(0.3, 0.42, 0.06), m);
          w.position.set(x, y, 0.82);
          g.add(w);
          wins.push(m);
        });
        const tm = winMat();
        const tw = new t.Mesh(new t.BoxGeometry(0.26, 0.34, 0.06), tm);
        tw.position.set(-0.86, 2.0, 0.52);
        g.add(tw);
        wins.push(tm);
        // dead tree
        g.add(cyl(t, 0.05, 0.1, 1.3, 0x241a12, [1.5, 0.65, 0.5], { tex: 'wood', repeat: [1, 3], rough: 1, seg: 8 }));
        [[-0.3, 1.2, 0.6], [0.35, 1.35, 0.4]].forEach(([x, y, z]) =>
          g.add(cyl(t, 0.02, 0.04, 0.5, 0x241a12, [1.5 + x, y, z], { rotZ: x, seg: 6 })),
        );
        return (time) => wins.forEach((m, i) => (m.emissiveIntensity = 0.55 + Math.abs(Math.sin(time * 3 + i * 1.7)) * 0.6));
      }}
    />
  );
}

import React from 'react';
import { SwingRide } from './index';

const previews = {
  componentName: 'SwingRide',
  importPath: 'components/SwingRide',
  previews: [
    { name: '3D rig', description: "Chair swing / wave-swinger: chained chairs flung out from a spinning canopy.", render: () => <SwingRide /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Chair swing / wave-swinger modelled from the RCT2 sprite: a central column
// with a spinning canopy from which chained chairs fly outward as it turns.
export function SwingRide() {
  return (
    <Stage
      distance={7.5}
      targetY={1.8}
      build={(t, g) => {
        const H = 3.4;
        g.add(cyl(t, 0.55, 0.65, 0.4, 0x8a8f98, [0, 0.2, 0], { tex: 'concrete', repeat: [6, 1], rough: 0.9, seg: 20 }));
        g.add(cyl(t, 0.18, 0.22, H, 0xd23a4a, [0, H / 2, 0], { tex: 'metal', metal: 0.6, rough: 0.4, seg: 16 }));
        const top = new t.Group();
        top.position.y = H;
        g.add(top);
        top.add(cyl(t, 1.05, 1.05, 0.14, 0xf5e050, [0, 0.12, 0], { tex: 'plastic', repeat: [12, 1], seg: 26 }));
        top.add(cyl(t, 0.06, 1.15, 0.55, 0xd23a4a, [0, 0.45, 0], { tex: 'plastic', repeat: [12, 1], seg: 26 }));
        const N = 8;
        for (let i = 0; i < N; i++) {
          const pivot = new t.Group();
          pivot.rotation.y = (i / N) * Math.PI * 2;
          top.add(pivot);
          const chair = new t.Group();
          chair.position.set(1.15, -0.35, 0);
          chair.rotation.z = -0.42; // flung outward
          pivot.add(chair);
          [-0.12, 0.12].forEach((x) => chair.add(cyl(t, 0.008, 0.008, 0.95, 0xcccccc, [x, 0.48, 0], { metal: 0.7, rough: 0.3, seg: 5 })));
          chair.add(box(t, [0.3, 0.06, 0.3], 0x2f6fd0, [0, 0, 0], { tex: 'plastic', rough: 0.4 }));
          chair.add(box(t, [0.3, 0.3, 0.06], 0x2f6fd0, [0, 0.15, -0.12], { tex: 'plastic', rough: 0.4 }));
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.36);
          p.group.position.y = 0.03;
          chair.add(p.group);
        }
        return (time) => {
          top.rotation.y = time * 1.0;
        };
      }}
    />
  );
}

import React from 'react';
import { GoKarts } from './index';

const previews = {
  componentName: 'GoKarts',
  importPath: 'components/GoKarts',
  previews: [
    { name: '3D rig', description: "Go-kart circuit: an oval asphalt track with four karts racing around it.", render: () => <GoKarts /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Go-karts modelled from the RCT2 track ride: an oval asphalt circuit with red
// kerbs and four karts (with drivers) racing around it.
export function GoKarts() {
  return (
    <Stage
      distance={7.5}
      targetY={0.5}
      build={(t, g) => {
        const R = 2.2;
        const track = new t.Mesh(new t.TorusGeometry(R, 0.62, 12, 60), new t.MeshStandardMaterial({ color: 0x3a3d42, roughness: 0.96 }));
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.06;
        track.receiveShadow = true;
        g.add(track);
        [R - 0.6, R + 0.6].forEach((rr) => {
          const k = new t.Mesh(new t.TorusGeometry(rr, 0.05, 8, 60), new t.MeshStandardMaterial({ color: 0xdd3838, roughness: 0.6 }));
          k.rotation.x = -Math.PI / 2;
          k.position.y = 0.14;
          g.add(k);
        });
        const cols = [0xe0201a, 0x2f6fd0, 0x2e9e54, 0xe0a020];
        const karts: THREE.Group[] = [];
        for (let i = 0; i < 4; i++) {
          const k = new t.Group();
          k.add(box(t, [0.32, 0.14, 0.62], 0x141417, [0, 0.14, 0], { tex: 'metal', metal: 0.5, rough: 0.5 }));
          k.add(box(t, [0.34, 0.16, 0.4], cols[i], [0, 0.26, -0.04], { tex: 'plastic', repeat: [1, 1], rough: 0.35 }));
          k.add(box(t, [0.22, 0.14, 0.22], 0x101014, [0, 0.32, -0.16], { rough: 0.8 }));
          k.add(cyl(t, 0.09, 0.09, 0.34, 0x0a0a0d, [0, 0.3, 0.28], { rotZ: Math.PI / 2, seg: 8, rough: 0.7 })); // steering column base
          [[-0.18, 0.22], [0.18, 0.22], [-0.18, -0.22], [0.18, -0.22]].forEach(([x, z]) =>
            k.add(cyl(t, 0.09, 0.09, 0.08, 0x141417, [x, 0.09, z], { rotZ: Math.PI / 2, seg: 12, tex: 'metal', metal: 0.4, rough: 0.5 })),
          );
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i], seated: true });
          p.group.scale.setScalar(0.36);
          p.group.position.set(0, 0.16, -0.05);
          k.add(p.group);
          g.add(k);
          karts.push(k);
        }
        return (time) => {
          karts.forEach((k, i) => {
            const a = time * 0.7 + (i / 4) * Math.PI * 2;
            k.position.set(Math.cos(a) * R, 0.1, Math.sin(a) * R);
            k.rotation.y = -a + Math.PI / 2;
          });
        };
      }}
    />
  );
}

import React from 'react';
import { MineTrainCar } from './index';

const previews = {
  componentName: 'MineTrainCar',
  importPath: 'components/MineTrainCar',
  previews: [
    { name: '3D rig', description: "Mine-train ore-cart vehicle with iron bands and a prospector.", render: () => <MineTrainCar /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep } from '../Guest';

// Mine-train car modelled from the RCT2 vehicle sprite: a wooden ore-cart tub
// bound with iron bands on a rustic rail, with a prospector aboard.
export function MineTrainCar() {
  return (
    <Stage
      distance={4.2}
      targetY={0.5}
      build={(t, g) => {
        for (let z = -1.4; z <= 1.4; z += 0.4) g.add(box(t, [0.98, 0.06, 0.12], 0x4a3018, [0, 0.02, z], { tex: 'wood', repeat: [3, 1], rough: 0.95 }));
        [-0.32, 0.32].forEach((x) => g.add(box(t, [0.08, 0.08, 3], 0x6a4a2a, [x, 0.09, 0], { tex: 'wood', repeat: [1, 20], rough: 0.85 })));
        const car = new t.Group();
        car.position.y = 0.26;
        g.add(car);
        car.add(box(t, [0.6, 0.42, 0.92], 0x6a4a2a, [0, 0.2, 0], { tex: 'wood', repeat: [3, 2], rough: 0.88 }));
        car.add(box(t, [0.5, 0.32, 0.8], 0x1a120a, [0, 0.28, 0], { rough: 0.92 }));
        [-0.26, 0.26].forEach((z) => car.add(box(t, [0.66, 0.36, 0.05], 0x2a2a2e, [0, 0.22, z], { tex: 'metal', metal: 0.6, rough: 0.5 })));
        car.add(box(t, [0.66, 0.05, 0.94], 0x2a2a2e, [0, 0.41, 0], { tex: 'metal', metal: 0.6, rough: 0.5 }));
        [[-0.3, 0.32], [0.3, 0.32], [-0.3, -0.32], [0.3, -0.32]].forEach(([x, z]) =>
          car.add(cyl(t, 0.1, 0.1, 0.07, 0x161619, [x, -0.05, z], { rotZ: Math.PI / 2, tex: 'metal', metal: 0.6, rough: 0.4, seg: 16 })),
        );
        const p = buildPeep(t, { shirt: 0x9a5a24, trousers: 0x3a2a1a, skin: 0xc68642, seated: true });
        p.group.scale.setScalar(0.5);
        p.group.position.y = 0.14;
        car.add(p.group);
        return (time) => {
          car.position.y = 0.26 + Math.sin(time * 2) * 0.012;
          car.rotation.z = Math.sin(time) * 0.02;
        };
      }}
    />
  );
}

import React from 'react';
import { BobsleighCar } from './index';

const previews = {
  componentName: 'BobsleighCar',
  importPath: 'components/BobsleighCar',
  previews: [
    { name: '3D rig', description: "Sleek two-seat bobsleigh on chrome runners in a banked chute.", render: () => <BobsleighCar /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep } from '../Guest';

// Bobsleigh car modelled from the RCT2 vehicle sprite: a sleek two-seat pod on
// chrome runners inside a banked half-pipe chute.
export function BobsleighCar() {
  return (
    <Stage
      distance={4.6}
      targetY={0.5}
      build={(t, g) => {
        g.add(box(t, [1.5, 0.12, 3], 0x9fb0c0, [0, 0.06, 0], { tex: 'concrete', repeat: [3, 10], rough: 0.9 }));
        [-0.75, 0.75].forEach((x) => g.add(box(t, [0.12, 0.55, 3], 0xbcc6d2, [x, 0.28, 0], { tex: 'concrete', repeat: [1, 10], rough: 0.9, rotZ: x > 0 ? -0.22 : 0.22 })));
        const sled = new t.Group();
        sled.position.y = 0.22;
        g.add(sled);
        sled.add(box(t, [0.42, 0.24, 1.25], 0x18306a, [0, 0.17, 0], { tex: 'plastic', repeat: [1, 3], rough: 0.3 }));
        sled.add(box(t, [0.46, 0.1, 1.3], 0x0f2050, [0, 0.06, 0], { tex: 'plastic', rough: 0.3 }));
        sled.add(box(t, [0.3, 0.22, 0.55], 0x0a1024, [0, 0.26, -0.12], { rough: 0.85 }));
        sled.add(box(t, [0.44, 0.18, 0.4], 0xc41f3a, [0, 0.2, 0.5], { rotX: -0.4, tex: 'plastic', rough: 0.3 })); // nose cowl
        [-0.19, 0.19].forEach((x) => sled.add(box(t, [0.04, 0.05, 1.34], 0xd0d4da, [x, -0.02, 0], { tex: 'metal', metal: 0.85, rough: 0.2 })));
        [0.28, -0.22].forEach((z, i) => {
          const p = buildPeep(t, { shirt: [0xd23a4a, 0xf0d000][i], seated: true, expression: 'surprised' });
          p.group.scale.setScalar(0.4);
          p.group.position.set(0, 0.14, z);
          sled.add(p.group);
        });
        return (time) => {
          sled.position.y = 0.22 + Math.sin(time * 2) * 0.01;
          sled.rotation.z = Math.sin(time * 1.5) * 0.06;
        };
      }}
    />
  );
}
